"""Hash-chained incident ledger (spec §7.3, Appendix E.2).

    h_0 = SHA-256("kintsugi-omega-genesis" ‖ T0 ‖ attest_pubkey)
    h_i = SHA-256(JCS(entry_i without "hash") ‖ h_{i-1})

Byte encodings: T0 is its RFC 3339 UTC string in UTF-8; the public key is its 32 raw Ed25519
bytes (or the DER SubjectPublicKeyInfo of a KMS key); h_{i-1} enters as its 32 raw digest
bytes. Hashes are stored as 64 lowercase hex characters. Every entry carries ``seq``
(1-based), ``prev`` (h_{i-1}) and ``hash`` (h_i), so a reader can locate a break exactly.

Verification finds the first broken ``seq``. An attacker who edits entry k and recomputes every
later hash produces a different head, which the published hourly anchors expose (audit C1).
The ledger never reads a clock: callers pass ``at``, keeping Temporal activities deterministic.
"""

from __future__ import annotations

import hashlib
import json
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass
from typing import Any

from kintsugi.proof.canonical import canonicalize

GENESIS_PREFIX = b"kintsugi-omega-genesis"
_RESERVED = ("seq", "prev", "hash")


class LedgerError(ValueError):
    pass


def genesis_hash(t0: str, attest_pubkey: bytes) -> str:
    return hashlib.sha256(GENESIS_PREFIX + t0.encode("utf-8") + attest_pubkey).hexdigest()


def entry_hash(entry: Mapping[str, Any], prev_hash: str) -> str:
    body = {key: value for key, value in entry.items() if key != "hash"}
    return hashlib.sha256(canonicalize(body) + bytes.fromhex(prev_hash)).hexdigest()


@dataclass(frozen=True)
class VerifyReport:
    ok: bool
    entries: int
    head: str
    first_bad_seq: int | None = None
    reason: str | None = None


def verify(
    entries: Sequence[Mapping[str, Any]],
    genesis: str,
    *,
    anchors: Mapping[int, str] | None = None,
) -> VerifyReport:
    """Verify the chain from h_0, then every anchor ``{seq: h_seq}`` (audit check C1)."""
    expected_prev = genesis
    for position, entry in enumerate(entries, start=1):
        seq = entry.get("seq")
        if seq != position:
            return _broken(position, expected_prev, f"expected seq {position}, found {seq!r}")
        if entry.get("prev") != expected_prev:
            return _broken(position, expected_prev, "prev does not link to the previous hash")
        if entry.get("hash") != entry_hash(entry, expected_prev):
            return _broken(position, expected_prev, "content does not match its hash")
        expected_prev = entry["hash"]
    for seq, anchored in sorted((anchors or {}).items()):
        if seq < 0 or seq > len(entries):
            return _broken(seq, expected_prev, f"anchor at seq {seq} is outside the ledger")
        actual = genesis if seq == 0 else entries[seq - 1]["hash"]
        if actual != anchored:
            return _broken(seq, expected_prev, f"anchor h_{seq} does not match the ledger")
    return VerifyReport(ok=True, entries=len(entries), head=expected_prev)


def _broken(seq: int, head: str, reason: str) -> VerifyReport:
    return VerifyReport(ok=False, entries=seq - 1, head=head, first_bad_seq=seq, reason=reason)


class Ledger:
    """An append-only, in-memory ledger with JSON Lines persistence."""

    def __init__(self, genesis: str, entries: Iterable[Mapping[str, Any]] = ()) -> None:
        self.genesis = genesis
        self._entries: list[dict[str, Any]] = [dict(entry) for entry in entries]
        report = verify(self._entries, genesis)
        if not report.ok:
            raise LedgerError(f"seq {report.first_bad_seq}: {report.reason}")

    @property
    def head(self) -> str:
        return self._entries[-1]["hash"] if self._entries else self.genesis

    @property
    def entries(self) -> tuple[dict[str, Any], ...]:
        return tuple(dict(entry) for entry in self._entries)

    def __len__(self) -> int:
        return len(self._entries)

    def append(self, entry: Mapping[str, Any]) -> dict[str, Any]:
        reserved = [key for key in _RESERVED if key in entry]
        if reserved:
            raise LedgerError(f"the ledger assigns these fields itself: {reserved}")
        for required in ("type", "at"):
            if not entry.get(required):
                raise LedgerError(f"entry needs a non-empty {required!r}")
        record = {"seq": len(self._entries) + 1, **entry, "prev": self.head}
        record["hash"] = entry_hash(record, self.head)
        self._entries.append(record)
        return dict(record)

    def to_jsonl(self) -> str:
        return "".join(canonicalize(entry).decode("utf-8") + "\n" for entry in self._entries)

    @classmethod
    def from_jsonl(cls, text: str, genesis: str) -> Ledger:
        entries = [json.loads(line) for line in text.splitlines() if line.strip()]
        return cls(genesis, entries)
"""Proof bundles (spec §7.4, Appendix E.3).

A bundle is stored as its canonical JSON bytes, so the SHA-256 of ``bundle.json`` on disk equals
the SHA-256 of the canonical object. That digest is what the incident's ledger entry records.
Attachments (trace exports, the cassette, graph outputs, gate reports) are listed by digest.
"""

from __future__ import annotations

import hashlib
import json
import os
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from pydantic import BaseModel, ConfigDict, Field

from kintsugi.proof.canonical import canonicalize

BUNDLE_FILE = "bundle.json"
MANIFEST_FILE = "attachments.json"


class ProofBundle(BaseModel):
    """Appendix E.3. Later stages fill more sections; unknown sections are preserved."""

    model_config = ConfigDict(extra="allow")

    incident: str
    host: str
    sealed_sabotage: dict[str, Any] | None = None
    traces: dict[str, list[str]] = Field(default_factory=dict)
    cassette: dict[str, Any] | None = None
    cause: dict[str, Any] | None = None
    rounds: list[dict[str, Any]] = Field(default_factory=list)
    dispute: dict[str, Any] | None = None
    winner: dict[str, Any] | None = None
    reverify: dict[str, str] | None = None
    ship: dict[str, Any] | None = None
    canary: dict[str, Any] | None = None
    cost: dict[str, Any] | None = None
    antibody: str | None = None

    def as_json(self) -> dict[str, Any]:
        return self.model_dump(mode="json", exclude_none=True)


def bundle_bytes(bundle: ProofBundle | Mapping[str, Any]) -> bytes:
    data = bundle.as_json() if isinstance(bundle, ProofBundle) else dict(bundle)
    return canonicalize(data)


def bundle_sha256(bundle: ProofBundle | Mapping[str, Any]) -> str:
    return "sha256:" + hashlib.sha256(bundle_bytes(bundle)).hexdigest()


def file_sha256(path: str | os.PathLike[str]) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 16), b""):
            digest.update(chunk)
    return "sha256:" + digest.hexdigest()


def write_bundle(directory: str | os.PathLike[str], bundle: ProofBundle) -> str:
    """Write ``bundle.json`` and the attachment manifest; return the bundle digest."""
    root = Path(directory)
    root.mkdir(parents=True, exist_ok=True)
    (root / BUNDLE_FILE).write_bytes(bundle_bytes(bundle))
    manifest = attachment_manifest(root)
    (root / MANIFEST_FILE).write_bytes(canonicalize(manifest))
    return bundle_sha256(bundle)


def read_bundle(directory: str | os.PathLike[str]) -> tuple[ProofBundle, str]:
    """Load a bundle and the digest of its on-disk bytes."""
    path = Path(directory) / BUNDLE_FILE
    return ProofBundle.model_validate(json.loads(path.read_bytes())), file_sha256(path)


def attachment_manifest(directory: str | os.PathLike[str]) -> dict[str, str]:
    root = Path(directory)
    return {
        path.relative_to(root).as_posix(): file_sha256(path)
        for path in sorted(root.rglob("*"))
        if path.is_file() and path.name not in (BUNDLE_FILE, MANIFEST_FILE)
    }


def verify_attachments(directory: str | os.PathLike[str]) -> list[str]:
    """Paths whose bytes no longer match the recorded manifest (missing, changed or new)."""
    root = Path(directory)
    recorded: dict[str, str] = json.loads((root / MANIFEST_FILE).read_bytes())
    current = attachment_manifest(root)
    return sorted(
        name for name in set(recorded) | set(current) if recorded.get(name) != current.get(name)
    )
"""Sealed-sabotage commit-reveal (spec §7.2, Appendix E.5).

    c = SHA-256(JCS(spec) ‖ salt),   salt = 32 random bytes

The commitment record published before delivery carries only ``id``, ``c``, ``sealed_at``,
``not_before`` and a coarse ``class_family``. The spec and salt are stored age-encrypted, and
only the Saboteur activity holds the identity that decrypts them. The reveal publishes both.
"""

from __future__ import annotations

import hashlib
import hmac
import json
import secrets
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

import pyrage

from kintsugi.proof.canonical import canonicalize

SALT_BYTES = 32
SPEC_FIELDS = (
    "id",
    "class",
    "target",
    "delivery",
    "ground_truth",
    "schedule",
    "honeytoken",
    "seed",
)


@dataclass(frozen=True)
class Seal:
    commitment: str
    salt: bytes


def commitment(spec: Mapping[str, Any], salt: bytes) -> str:
    if len(salt) != SALT_BYTES:
        raise ValueError(f"salt must be {SALT_BYTES} bytes")
    return "sha256:" + hashlib.sha256(canonicalize(spec) + salt).hexdigest()


def seal(spec: Mapping[str, Any], *, salt: bytes | None = None) -> Seal:
    check_spec_shape(spec)
    chosen = secrets.token_bytes(SALT_BYTES) if salt is None else salt
    return Seal(commitment=commitment(spec, chosen), salt=chosen)


def verify_reveal(published: str, spec: Mapping[str, Any], salt: bytes) -> bool:
    try:
        recomputed = commitment(spec, salt)
    except ValueError:
        return False
    return hmac.compare_digest(published, recomputed)
    return hmac.compare_digest(published, recomputed)


def check_spec_shape(spec: Mapping[str, Any]) -> None:
    missing = [name for name in SPEC_FIELDS if name not in spec]
    if missing:
        raise ValueError(f"sabotage spec is missing {missing}")


def class_family(sabotage_class: str) -> str:
    """The coarse family published before reveal: the class without its last component."""
    parts = sabotage_class.split(".")
    if len(parts) < 2 or not all(parts):
        raise ValueError(f"not a catalog class: {sabotage_class!r}")
    return ".".join(parts[:-1])


def commitment_record(
    spec: Mapping[str, Any], sealed: Seal, *, sealed_at: str, not_before: str
) -> dict[str, str]:
    """The public record (E.5, before its attestation is added)."""
    return {
        "id": str(spec["id"]),
        "c": sealed.commitment,
        "sealed_at": sealed_at,
        "not_before": not_before,
        "class_family": class_family(str(spec["class"])),
    }


def reveal_record(spec: Mapping[str, Any], sealed: Seal) -> dict[str, Any]:
    return {"spec": dict(spec), "salt": sealed.salt.hex()}


def new_identity() -> tuple[str, str]:
    """A fresh age X25519 identity: (secret ``AGE-SECRET-KEY-1…``, recipient ``age1…``)."""
    identity = pyrage.x25519.Identity.generate()
    return str(identity), str(identity.to_public())


def encrypt_sealed(spec: Mapping[str, Any], sealed: Seal, recipients: Sequence[str]) -> bytes:
    if not recipients:
        raise ValueError("at least one age recipient is required")
    payload = canonicalize({"spec": dict(spec), "salt": sealed.salt.hex()})
    keys = [pyrage.x25519.Recipient.from_str(recipient) for recipient in recipients]
    return pyrage.encrypt(payload, keys)


def decrypt_sealed(ciphertext: bytes, identity: str) -> tuple[dict[str, Any], Seal]:
    payload = json.loads(pyrage.decrypt(ciphertext, [pyrage.x25519.Identity.from_str(identity)]))
    spec = payload["spec"]
    salt = bytes.fromhex(payload["salt"])
    return spec, Seal(commitment=commitment(spec, salt), salt=salt)


def honeytoken_hits(
    repo: PathLike, token: str, refs: Iterable[str] | None = None
) -> list[tuple[str, str]]:
    """(ref, path) pairs whose stored content contains ``token`` verbatim (audit C6)."""
    targets = checkpoint_refs(repo) if refs is None else list(refs)
    if not targets:
        return []
    result = proc.run(
        ["git", "-C", os.fspath(repo), "grep", "-F", "-l", "-e", token, *targets], timeout_s=300
    )
    if result.returncode == 1:  # git grep: no match
        return []
    if not result.ok:
        raise RuntimeError(f"git grep failed: {result.stderr.strip()[-500:]}")
    hits = []
    for line in result.stdout.splitlines():
        ref, _, path = line.partition(":")
        hits.append((ref, path))
    return hits

"""Orchestrator commits and the autonomy checks C2–C5 (spec §4.5, §7.5; plan §2a, §2b, §2d).

**Commit protocol** (:func:`orchestrator_commit`), run after a headless session exits:

1. stage everything in the worktree; refuse protected-path violations and an over-budget diff;
2. compute the tree SHA (``git write-tree``) and sign the attestation over it;
3. commit with the ``Kintsugi-*`` trailers under ``ENTIRE_TEST_TTY=0`` (the gateway forces it);
   Entire's ``prepare-commit-msg`` hook appends ``Entire-Checkpoint:``;
4. verify the commit kept the signed tree and parent, carries no forbidden trailer, and names a
   checkpoint whose ref exists. Otherwise the commit is undone (``reset --soft``) and refused,
   so an unlinked commit is never pushed.

**Checks** (:func:`verify_commit`), usable online or offline from the refs alone:

- C2 every ``Kintsugi-*`` trailer is present and no ``Co-authored-by:``/``Claude-Session:``;
- C3 the signature verifies over (nonce, tree, parent, role, incident, prompt hash);
- C4 the named checkpoint exists, its stored transcript is intact (``content_hash``), contains
  the nonce verbatim, and its ``files_touched`` covers the commit's changed files;
- C5 the first user prompt of the session hashes to ``Kintsugi-Prompt``.

``Kintsugi-Prompt`` is ``sha256`` of the exact UTF-8 bytes of the session's first prompt; the
attestation's ``prompt_template_sha`` field carries that same digest (Amendments log).
"""

from __future__ import annotations

import hashlib
import json
import re
from collections.abc import Iterable
from dataclasses import dataclass, field, replace
from pathlib import Path

from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

from kintsugi.gates.protected_paths import Policy
from kintsugi.memory import entire
from kintsugi.proof import attest
from kintsugi.sandbox import proc


# ---- C2–C5 ----------------------------------------------------------------------------------


def first_user_prompt(transcript: bytes) -> str | None:
    """The first real user prompt in a Claude Code native (``full.jsonl``) transcript."""
    for raw in transcript.splitlines():
        try:
            entry = json.loads(raw)
        except json.JSONDecodeError:
            continue
        if not isinstance(entry, dict) or entry.get("type") != "user" or entry.get("isMeta"):
            continue
        content = (entry.get("message") or {}).get("content")
        if isinstance(content, str):
            return content
        if isinstance(content, list):
            blocks = [b for b in content if isinstance(b, dict) and b.get("type") == "text"]
            texts = [str(b.get("text", "")) for b in blocks]
            if texts:
                return "".join(texts)
    return None


def check_c4(
    stored: entire.StoredCheckpoint, nonce: str, changed_paths: Iterable[str]
) -> list[str]:
    problems: list[str] = []
    if not stored.sessions:
        return ["checkpoint has no sessions"]
    if not all(session.intact for session in stored.sessions):
        problems.append("a stored transcript does not match its content_hash")
    if not any(nonce.encode("utf-8") in session.full for session in stored.sessions):
        problems.append("the attested nonce is not in any session transcript")
    untouched = sorted(set(changed_paths) - set(stored.files_touched))
    if untouched:
        problems.append(f"changed files the checkpoint does not record: {untouched}")
    return problems


def check_c5(stored: entire.StoredCheckpoint, expected_prompt_digest: str) -> list[str]:
    for session in stored.sessions:
        prompt = first_user_prompt(session.full)
        if prompt is not None and prompt_digest(prompt) == expected_prompt_digest:
            return []
    return ["no session's first prompt hashes to Kintsugi-Prompt"]


@dataclass(frozen=True)
class LinkageReport:
    commit: str
    checkpoint_id: str | None
    problems: dict[str, list[str]] = field(default_factory=dict)

    @property
    def ok(self) -> bool:
        return not any(self.problems.values())


def verify_commit(repo: Path, sha: str, *, public_key: Ed25519PublicKey) -> LinkageReport:
    """Checks C2–C5 for one commit, from git and the checkpoint refs alone."""
    repo = Path(repo)
    message = _git(repo, "log", "-1", "--format=%B", sha)
    trailers = attest.parse_trailers(message)
    problems: dict[str, list[str]] = {
        "C2": message_problems(message, require_attestation=True, require_checkpoint=True)
    }
    checkpoint_id = (trailers.get(attest.ENTIRE_TRAILER) or [None])[0]
    if problems["C2"]:
        return LinkageReport(sha, checkpoint_id, problems)
    one = {key: values[0] for key, values in trailers.items()}
    claimed = attest.SessionAttestation(
        nonce=one["Kintsugi-Nonce"], role=one["Kintsugi-Role"], incident=one["Kintsugi-Incident"],
        worktree="", base_sha="", prompt_template_sha=one["Kintsugi-Prompt"], t_start="",
        tree_sha=_git(repo, "rev-parse", f"{sha}^{{tree}}").strip(),
        parent_sha=_git(repo, "rev-parse", f"{sha}^").strip(),
        signature=one["Kintsugi-Attestation"],
    )  # fmt: skip
    problems["C3"] = [] if attest.verify_attestation(claimed, public_key) else ["bad signature"]
    try:
        stored = entire.read_checkpoint(repo, str(checkpoint_id))
    except entire.EntireError as error:
        problems["C4"] = [str(error)]
        problems["C5"] = ["no checkpoint to read the prompt from"]
        return LinkageReport(sha, checkpoint_id, problems)
    changed = [p for p in _git(repo, "diff-tree", "--no-commit-id", "--name-only", "-r", "-z", sha)
               .split("\0") if p]  # fmt: skip
    problems["C4"] = check_c4(stored, claimed.nonce, changed)
    problems["C5"] = check_c5(stored, claimed.prompt_template_sha)
    return LinkageReport(sha, checkpoint_id, problems)


def why_agrees(repo: Path, sha: str, checkpoint_id: str, *, samples: int = 3) -> list[str]:
    """Cross-check with ``entire why``: sampled added lines resolve to this commit and its
    checkpoint."""
    problems: list[str] = []
    diff = _git(Path(repo), "show", "--format=", "--unified=0", sha)
    targets: list[tuple[str, int]] = []
    path = None
    for line in diff.splitlines():
        if line.startswith("+++ b/"):
            path = line[6:]
        elif line.startswith("@@") and path is not None:
            match = re.search(r"\+(\d+)", line)
            if match:
                targets.append((path, int(match.group(1))))
    for path_, number in targets[:samples]:
        found = entire.why(repo, path_, number)
        if found.checkpoint_id != checkpoint_id or not found.commit_sha.startswith(sha[:7]):
            problems.append(f"{path_}:{number} → {found.checkpoint_id} @ {found.commit_sha[:8]}")
    return problems


def strip_nonce(stored: entire.StoredCheckpoint, nonce: str) -> entire.StoredCheckpoint:
    """A mutated copy without the nonce (keeps content_hash): the negative control for C4."""
    sessions = [replace(s, full=s.full.replace(nonce.encode(), b"")) for s in stored.sessions]
    return replace(stored, sessions=sessions)

@dataclass(frozen=True)
class SessionAttestation:
    """Appendix E.6. ``tree_sha``, ``parent_sha`` and ``signature`` are filled at commit time."""

    nonce: str
    role: str
    incident: str
    worktree: str
    base_sha: str
    prompt_template_sha: str
    t_start: str
    hypothesis: str | None = None
    tree_sha: str | None = None
    parent_sha: str | None = None
    signature: str | None = None

    @property
    def role_label(self) -> str:
        return f"{self.role}/{self.hypothesis}" if self.hypothesis else self.role


def signing_digest(
    nonce: str,
    tree_sha: str,
    parent_sha: str,
    role: str,
    incident: str,
    prompt_template_sha: str,
) -> bytes:
    fields = [nonce, tree_sha, parent_sha, role, incident, prompt_template_sha]
    return hashlib.sha256(canonicalize(fields)).digest()


def _digest_for(att: SessionAttestation) -> bytes:
    if att.tree_sha is None or att.parent_sha is None:
        raise ValueError("tree_sha and parent_sha are required to sign or verify")
    return signing_digest(
        att.nonce, att.tree_sha, att.parent_sha, att.role_label, att.incident,
        att.prompt_template_sha,
    )  # fmt: skip


def attest(
    att: SessionAttestation, signer: Signer, *, tree_sha: str, parent_sha: str
) -> SessionAttestation:
    if not is_nonce(att.nonce):
        raise ValueError("the nonce must be a 128-bit passphrase (spike N1)")
    filled = replace(att, tree_sha=tree_sha, parent_sha=parent_sha)
    signature = base64.b64encode(signer.sign(_digest_for(filled))).decode("ascii")
    return replace(filled, signature=f"{signer.algorithm}:{signature}")


def verify_attestation(att: SessionAttestation, public_key: Ed25519PublicKey) -> bool:
    if att.signature is None or not att.signature.startswith("ed25519:"):
        return False
    try:
        signature = base64.b64decode(att.signature.removeprefix("ed25519:"), validate=True)
        public_key.verify(signature, _digest_for(att))
    except (InvalidSignature, ValueError):
        return False
    return True


def trailers(att: SessionAttestation) -> list[tuple[str, str]]:
    if att.signature is None:
        raise ValueError("sign the attestation before writing trailers")
    values = [att.incident, att.role_label, att.nonce, att.prompt_template_sha, att.signature]
    return list(zip(TRAILER_KEYS, values, strict=True))


def format_trailers(pairs: list[tuple[str, str]]) -> str:
    return "\n".join(f"{key}: {value}" for key, value in pairs)


def parse_trailers(message: str) -> dict[str, list[str]]:
    """Trailers from the trailing trailer-only paragraphs of a commit message.

    Consecutive trailing paragraphs that consist only of ``Key: value`` lines are merged, so the
    orchestrator's ``Kintsugi-*`` block and an ``Entire-Checkpoint:`` line that a hook appends
    in its own paragraph are read together. The subject line is never a trailer.
    """
    paragraphs = [block for block in re.split(r"\n\s*\n", message.strip()) if block.strip()]
    parsed: dict[str, list[str]] = {}
    for block in reversed(paragraphs[1:]):
        matches = [_TRAILER_LINE.match(line.strip()) for line in block.splitlines()]
        if not all(matches):
            break  # prose: the trailer section ends here
        for match in reversed(matches):
            assert match is not None
            parsed.setdefault(match.group(1), []).insert(0, match.group(2).strip())
    return parsed


def commit_message_problems(message: str, *, require_attestation: bool) -> list[str]:
    """Policy check run before every commit the orchestrator makes."""
    problems: list[str] = []
    if _COAUTHOR.search(message):
        problems.append("Co-authored-by trailers are forbidden (ruling D4)")
    if require_attestation:
        found = parse_trailers(message)
        missing = [key for key in TRAILER_KEYS if key not in found]
        if missing:
            problems.append(f"missing attestation trailers: {missing}")
    return problems

